def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """

    # Create a new class with the given name and fields
    class _Point(Point):
        __slots__ = ()
        _fformat = "(%s)" % ", ".join(["%r" if f is None else "%s=%%r" % f for f in fields])

        def __init__(self, *args):
            if len(args) != len(fields):
                raise ValueError("Invalid number of arguments")
            for i, a in enumerate(args):
                if fields[i] is not None:
                    vars()[fields[i]] = a
            del i, a

        def __repr__(self):
            return "Point(%s)" % ", ".join([str(getattr(self, f)) for f in fields])

    # Add the srid_map to the class
    _Point._srid_map = srid_map

    return _Point

