def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Iterate through all objects in the hierarchy
    for obj in self.get_objects():
        num_objects += 1

        # Check if the object is valid
        if validate_objects:
            if self.is_valid_object(obj):
                good_objects += 1
            else:
                if show_warnings:
                    print(f"Object {obj} is not valid")

        # Check if the object's digest is valid
        if check_digests:
            if self.is_valid_digest(obj):
                good_objects += 1
            else:
                if show_warnings:
                    print(f"Object {obj} has an invalid digest")

    return num_objects, good_objects

