        return None
    m = re.match(r'^(\d+)\s*(\w+)$', frequency)
    if not m:
        raise ValueError("Invalid frequency string")
    num = int(m.group(1))
    unit = m.group(2)
    if unit == "years":
        return datetime.timedelta(weeks=num * 52)
