def validate_from_content(spec_content):
    """
    Validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """

    # Load the spec content into a dictionary
    spec_data = yaml.load(spec_content, Loader=yaml.FullLoader)

    # Check if the spec data has all required fields
    for field in cls.REQUIRED_FIELDS:
        if field not in spec_data:
            raise IRValidatorException(f"Mandatory field '{field}' is missing in spec file")

    # Check if the spec data has all required fields with the correct types
    for field, field_type in cls.REQUIRED_FIELDS_TYPES.items():
        if field not in spec_data or not isinstance(spec_data[field], field_type):
            raise IRValidatorException(f"Field '{field}' in spec file has incorrect type, expected {field_type}")

    # Check if the spec data has all required fields with the correct values
    for field, field_values in cls.REQUIRED_FIELDS_VALUES.items():
        if field not in spec_data or spec_data[field] not in field_values:
            raise IRValidatorException(f"Field '{field}' in spec file has incorrect value, expected one of {field_values}")

    return spec_data

