def _include_groups(self, parser_dict):
    """
    Resolves the include dict directive in the spec files.

    :param dict parser_dict:
    """
    for key, value in parser_dict.items():
        if isinstance(value, dict):
            self._include_groups(value)
        elif key == 'include':
            include_dict = value
            for include_key, include_value in include_dict.items():
                if include_key in parser_dict:
                    raise ValueError('Duplicate key in include dict: %r' % (include_key,))
                parser_dict[include_key] = include_value

